#[derive(Clone, Debug, Eq, PartialEq)]
struct CapabilityCapturedPriorProjection {
    pub(crate) bytes: Vec<u8>,
    pub(crate) intent: ProjectionIntent,
    pub(crate) completion: ProjectionCompletion,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum CapabilityCapturedProjectionState {
    Absent,
    Present {
        bytes: Vec<u8>,
        prior_intent: ProjectionIntent,
        prior_completion: ProjectionCompletion,
    },
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum CapabilityCapturedProjectionMaterial {
    Absent {
        prior: Option<CapabilityCapturedPriorProjection>,
    },
    Present {
        bytes: Vec<u8>,
        annotations: Vec<AnnotatedIdentity>,
        prior: Option<CapabilityCapturedPriorProjection>,
    },
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct CapabilityCapturedProjectionInput {
    path: ManagedPath,
    endpoint: ProjectionEndpointBinding,
    receipt_store_id: super::ProjectionReceiptStoreId,
    state: CapabilityCapturedProjectionState,
    material: CapabilityCapturedProjectionMaterial,
    draft_completed_path: Option<Vec<super::ProjectionCompletedReceipt>>,
}

impl CapabilityCapturedProjectionInput {
    pub(crate) fn from_graph_capability(
        path: ManagedPath,
        endpoint: ProjectionEndpointBinding,
        receipt_store_id: super::ProjectionReceiptStoreId,
        state: CapabilityCapturedProjectionState,
    ) -> Self {
        let material = match &state {
            CapabilityCapturedProjectionState::Absent => {
                CapabilityCapturedProjectionMaterial::Absent { prior: None }
            }
            CapabilityCapturedProjectionState::Present {
                bytes,
                prior_intent,
                prior_completion,
            } => CapabilityCapturedProjectionMaterial::Present {
                bytes: bytes.clone(),
                annotations: prior_intent.annotations().to_vec(),
                prior: Some(CapabilityCapturedPriorProjection {
                    bytes: bytes.clone(),
                    intent: prior_intent.clone(),
                    completion: prior_completion.clone(),
                }),
            },
        };
        Self {
            path,
            endpoint,
            receipt_store_id,
            state,
            material,
            draft_completed_path: None,
        }
    }

    fn from_draft_capability(
        path: ManagedPath,
        endpoint: ProjectionEndpointBinding,
        receipt_store_id: super::ProjectionReceiptStoreId,
        material: CapabilityCapturedProjectionMaterial,
    ) -> Self {
        // Draft-only external capture can represent a newly present path or an
        // absent path with prior completion authority. That richer material is
        // deliberately private; the original public state enum remains source
        // compatible and is not used as the draft's authority.
        let state = match &material {
            CapabilityCapturedProjectionMaterial::Present {
                bytes,
                prior: Some(prior),
                ..
            } => CapabilityCapturedProjectionState::Present {
                bytes: bytes.clone(),
                prior_intent: prior.intent.clone(),
                prior_completion: prior.completion.clone(),
            },
            CapabilityCapturedProjectionMaterial::Absent { .. }
            | CapabilityCapturedProjectionMaterial::Present { prior: None, .. } => {
                CapabilityCapturedProjectionState::Absent
            }
        };
        Self {
            path,
            endpoint,
            receipt_store_id,
            state,
            material,
            draft_completed_path: None,
        }
    }

    pub fn path(&self) -> &ManagedPath {
        &self.path
    }
}

struct DraftProjectionPage {
    before: Option<ProjectionPageState>,
    after: Option<ProjectionPageState>,
    post_frontier: FrontierV2,
}

/// Speculative author state. Only bounded path requirements are observable;
/// CRDT buffers, semantic effects, and the prospective object set remain
/// private until exact endpoint inputs finalize the closed batch.
pub struct AuthorTransactionDraft {
    author: AuthorBatch,
    origin: BatchOrigin,
    generation: u64,
    root_token: ContentDigest,
    prepared_core: PreparedBatch,
    semantic_effect: SemanticEffect,
    portable_path_root: PortablePathIndexRoot,
    prospective_documents: BTreeMap<DocumentId, LoroDoc>,
    requirements: Vec<ProjectionRequirement>,
    pages: BTreeMap<PageId, DraftProjectionPage>,
    external_observation: Option<ExternalImportObservationMaterial>,
}

impl AuthorTransactionDraft {
    pub fn requirements(&self) -> &[ProjectionRequirement] {
        &self.requirements
    }

    /// Freshly capture the exact graph bytes and authenticated completed-path
    /// authority owned by this draft. The caller never reconstructs which
    /// rename bases or prior receipts are required.
    pub(crate) fn capture_projection_inputs(
        &self,
        engine: &ShardedHotEngine,
        graph: &Graph,
        receipts: &ProjectionReceiptStore,
        endpoint: ProjectionEndpointBinding,
    ) -> Result<Vec<CapabilityCapturedProjectionInput>, EngineError> {
        if self.generation != engine.history_generation
            || self.root_token != engine.author_generation_root()?
        {
            return Err(EngineError::AuthorDraftStale);
        }
        let (_, work_index) = engine.enrolled_projection_runtime()?;
        if receipts.workspace_id() != engine.workspace_id
            || receipts.endpoint_binding() != Some(endpoint)
            || receipts.store_id() != work_index.receipt_store_id()
        {
            return Err(EngineError::ProjectionManifest(
                "draft capture is not bound to the enrolled projection runtime".into(),
            ));
        }
        let external_observation = self.external_observation.as_ref().ok_or_else(|| {
            EngineError::ProjectionManifest(
                "external reconciliation draft has no sealed observation".into(),
            )
        })?;
        for entry in external_observation.entries() {
            let current = graph
                .read_projection_input(entry.path())
                .map_err(|error| EngineError::ProjectionManifest(error.to_string()))?;
            if current.as_deref() != entry.state().bytes() {
                return Err(EngineError::ProjectionManifest(format!(
                    "draft observation for {} is stale",
                    entry.path()
                )));
            }
        }
        let paths = self
            .requirements
            .iter()
            .flat_map(|requirement| {
                std::iter::once(requirement.path.clone())
                    .chain(requirement.render_base_path.iter().cloned())
            })
            .collect::<BTreeSet<_>>();
        let mut captured = Vec::with_capacity(paths.len());
        for path in paths {
            let observed = external_observation
                .entries()
                .iter()
                .find(|entry| entry.path() == &path)
                .ok_or_else(|| {
                    EngineError::ProjectionManifest(format!(
                        "draft path {path} has no exact fresh external observation"
                    ))
                })?;
            let completed = work_index
                .completed_receipts_for_path(&path)
                .map_err(|error| EngineError::ProjectionWork(error.to_string()))?;
            let prior_requirement = self.requirements.iter().find(|requirement| {
                self.pages[&requirement.page_id]
                    .before
                    .as_ref()
                    .is_some_and(|before| before.page.path == path)
            });
            let prior = if let Some(requirement) = prior_requirement {
                let authority = match completed.as_slice() {
                    [authority]
                        if matches!(authority.target(), ProjectionWorkTarget::Present(_)) =>
                    {
                        authority
                    }
                    _ => {
                        return Err(EngineError::ProjectionManifest(format!(
                            "draft path {path} has no unique completed present authority"
                        )));
                    }
                };
                let (intent, completion) = receipts
                    .load_completed_receipt(authority)
                    .map_err(|error| EngineError::ProjectionManifest(error.to_string()))?;
                let before = self.pages[&requirement.page_id]
                    .before
                    .as_ref()
                    .ok_or_else(|| {
                        EngineError::ProjectionManifest(format!(
                            "draft path {path} has completion authority without semantic pre-state"
                        ))
                    })?;
                let base = receipts
                    .load_base(&intent)
                    .map_err(|error| EngineError::ProjectionManifest(error.to_string()))?;
                let replay = super::projection::plan_projection(
                    engine.workspace_id,
                    before,
                    base.as_ref().map(super::BaseBlob::bytes),
                )
                .map_err(|error| EngineError::ProjectionManifest(error.to_string()))?;
                if replay.intent() != &intent {
                    return Err(EngineError::ProjectionManifest(format!(
                        "draft path {path} completion cannot reproduce its exact rendered bytes"
                    )));
                }
                Some(CapabilityCapturedPriorProjection {
                    bytes: replay.target().to_vec(),
                    intent,
                    completion,
                })
            } else {
                if !completed.is_empty() {
                    return Err(EngineError::ProjectionManifest(format!(
                        "draft path {path} has completion authority unrelated to its semantic predecessor"
                    )));
                }
                None
            };
            let state = match observed.state() {
                super::external_import::ExternalImportObservationState::Absent => {
                    CapabilityCapturedProjectionMaterial::Absent { prior }
                }
                super::external_import::ExternalImportObservationState::Present {
                    bytes,
                    annotations,
                } => CapabilityCapturedProjectionMaterial::Present {
                    bytes: bytes.clone(),
                    annotations: annotations.clone(),
                    prior,
                },
            };
            let mut input = CapabilityCapturedProjectionInput::from_draft_capability(
                path,
                endpoint,
                receipts.store_id(),
                state,
            );
            input.draft_completed_path = Some(completed);
            captured.push(input);
        }
        Ok(captured)
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct AcceptedBatch {
    pub batch_id: BatchId,
    pub no_op: bool,
}

#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct AcceptedBatchEvidence {
    schema_version: u32,
    batch_id: BatchId,
    manifest_fingerprint: ContentDigest,
    event_binding_digest: ContentDigest,
    acceptance_sequence: u64,
    prior_frontier_root: AcceptedFrontierRoot,
    post_frontier_root: AcceptedFrontierRoot,
    affected_documents: Vec<DocumentDependencies>,
    reference_catalog_delta: ReferenceCatalogDeltaV2,
}

#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
/// Device-local evidence for a derived accepted-frontier projection.
///
/// This value authenticates local engine and SQLite projection transitions. It
/// is deliberately not a protocol frontier, interchange format, or portable
/// export representation: its state is acceptance-order dependent and may
/// contain run-local scratch-store references. Its Serde encoding exists only
/// for Tine's validated local evidence/archive paths and carries no wire-format
/// stability claim.
#[non_exhaustive]
pub struct AcceptedFrontierRoot {
    schema_version: u32,
    acceptance_sequence: u64,
    document_count: u64,
    retained_bytes_total: u64,
    document_map_root_key: Option<[u8; 16]>,
    document_map_root_digest: ContentDigest,
    // Commits every accepted BatchId to its immutable manifest/event binding,
    // causal dot, and authenticated sparse-clock root.
    batch_map_root_key: Option<[u8; 16]>,
    batch_map_root_digest: ContentDigest,
    reference_catalog_root: ReferenceCatalogRootV2,
    state_digest: ContentDigest,
    scratch_root: Option<super::scratch_store::ScratchLsmRoot>,
}

impl AcceptedBatchEvidence {
    #[cfg(test)]
    #[allow(clippy::too_many_arguments)]
    pub(crate) fn for_test(
        batch_id: BatchId,
        manifest_fingerprint: ContentDigest,
        event_binding_digest: ContentDigest,
        prior_frontier_root: AcceptedFrontierRoot,
        affected_documents: Vec<DocumentDependencies>,
        all_documents: Vec<DocumentDependencies>,
        accepted_batch_entries: Vec<(BatchId, ContentDigest)>,
        retained_bytes: u64,
    ) -> Self {
        let acceptance_sequence = prior_frontier_root.acceptance_sequence.saturating_add(1);
        let (document_map_root_key, document_map_root_digest) =
            authenticated_document_map_root(&all_documents)
                .expect("canonical test authenticated document map");
        let (batch_map_root_key, batch_map_root_digest) =
            authenticated_map_root(&accepted_batch_entries)
                .expect("canonical test authenticated batch map");
        let reference_catalog_root = prior_frontier_root.reference_catalog_root.clone();
        let post_frontier_root = next_accepted_frontier_root(
            &prior_frontier_root,
            event_binding_digest,
            acceptance_sequence,
            all_documents.len() as u64,
            retained_bytes,
            &affected_documents,
            document_map_root_key,
            document_map_root_digest,
            batch_map_root_key,
            batch_map_root_digest,
            reference_catalog_root.clone(),
            None,
        )
        .expect("canonical test accepted-frontier transition");
        Self {
            schema_version: ACCEPTED_EVIDENCE_SCHEMA_VERSION,
            batch_id,
            manifest_fingerprint,
            event_binding_digest,
            acceptance_sequence,
            prior_frontier_root,
            post_frontier_root,
            affected_documents,
            reference_catalog_delta: ReferenceCatalogDeltaV2::empty_transition(
                reference_catalog_root,
            ),
        }
    }

    pub const fn batch_id(&self) -> BatchId {
        self.batch_id
    }

    pub const fn manifest_fingerprint(&self) -> ContentDigest {
        self.manifest_fingerprint
    }

    pub const fn event_binding_digest(&self) -> ContentDigest {
        self.event_binding_digest
    }

    pub(crate) fn binding_digest_for(
        batch_id: BatchId,
        manifest_fingerprint: ContentDigest,
        semantic_effect_digest: SemanticEffectDigest,
        dependency_frontier: &FrontierV2,
        causal_dependency_heads: &[BatchId],
    ) -> Result<ContentDigest, EngineError> {
        let bytes = postcard::to_allocvec(&(
            b"tine/oplog/accepted-event-binding/v1".as_slice(),
            batch_id,
            manifest_fingerprint,
            semantic_effect_digest,
            dependency_frontier,
            causal_dependency_heads,
        ))
        .map_err(|error| EngineError::Archive(error.to_string()))?;
        Ok(ContentDigest::of(&bytes))
    }

    pub const fn acceptance_sequence(&self) -> u64 {
        self.acceptance_sequence
    }

    pub const fn prior_frontier_root(&self) -> &AcceptedFrontierRoot {
        &self.prior_frontier_root
    }

    pub const fn post_frontier_root(&self) -> &AcceptedFrontierRoot {
        &self.post_frontier_root
    }

    pub fn affected_documents(&self) -> &[DocumentDependencies] {
        &self.affected_documents
    }

    pub const fn reference_catalog_delta(&self) -> &ReferenceCatalogDeltaV2 {
        &self.reference_catalog_delta
    }

    pub(crate) fn validate(&self) -> Result<(), EngineError> {
        validate_accepted_evidence(self)
    }
}

impl AcceptedFrontierRoot {
    pub fn empty() -> Self {
        empty_accepted_frontier_root()
    }

    pub const fn acceptance_sequence(&self) -> u64 {
        self.acceptance_sequence
    }

    pub const fn document_count(&self) -> u64 {
        self.document_count
    }

    pub const fn retained_bytes_total(&self) -> u64 {
        self.retained_bytes_total
    }

    pub const fn document_map_root_key(&self) -> Option<[u8; 16]> {
        self.document_map_root_key
    }

    pub const fn document_map_root_digest(&self) -> ContentDigest {
        self.document_map_root_digest
    }

    pub const fn batch_map_root_key(&self) -> Option<[u8; 16]> {
        self.batch_map_root_key
    }

    pub const fn batch_map_root_digest(&self) -> ContentDigest {
        self.batch_map_root_digest
    }

    pub const fn state_digest(&self) -> ContentDigest {
        self.state_digest
    }

    pub const fn reference_catalog_root(&self) -> &ReferenceCatalogRootV2 {
        &self.reference_catalog_root
    }

    pub(crate) const fn has_persistent_point_index(&self) -> bool {
        self.scratch_root.is_some()
    }

    pub(crate) fn validates_transition(
        &self,
        event_binding_digest: ContentDigest,
        acceptance_sequence: u64,
        document_count: u64,
        retained_bytes: u64,
        affected_documents: &[DocumentDependencies],
        post: &Self,
    ) -> Result<bool, EngineError> {
        Ok(next_accepted_frontier_root(
            self,
            event_binding_digest,
            acceptance_sequence,
            document_count,
            retained_bytes,
            affected_documents,
            post.document_map_root_key,
            post.document_map_root_digest,
            post.batch_map_root_key,
            post.batch_map_root_digest,
            post.reference_catalog_root.clone(),
            post.scratch_root.clone(),
        )? == *post)
    }
}

