    /// Construct a sparse engine that follows compact direct heads through
    /// immutable manifests on cold fallback. Accepted non-catalog shards are
    /// evicted from hot memory and reconstructed from authenticated DAG
    /// ancestry on demand.
    pub fn with_archive_store(
        store: ObjectStore,
        lineage_digest: LineageDigest,
        catalog_document_id: DocumentId,
    ) -> Self {
        let workspace_id = store.workspace_id();
        let mut engine = Self::new(workspace_id, lineage_digest, catalog_document_id);
        match store.open_logseq_claim_index() {
            Ok(index) => engine.logseq_claim_index = Some(Arc::new(index)),
            Err(error) => engine.history_failure = Some(EngineError::Archive(error.to_string())),
        }
        match store.open_portable_path_index() {
            Ok(index) => engine.portable_path_index = Some(Arc::new(index)),
            Err(error) => engine.history_failure = Some(EngineError::Archive(error.to_string())),
        }
        match store.open_page_name_ownership_index() {
            Ok(index) => engine.page_name_index = Some(Arc::new(index)),
            Err(error) => engine.history_failure = Some(EngineError::Archive(error.to_string())),
        }
        match store.open_reference_catalog() {
            Ok(catalog) => {
                if let Err(error) = engine.reference_catalog.attach_store(Arc::new(catalog)) {
                    engine.history_failure = Some(EngineError::ReferenceCatalog(error.to_string()));
                }
            }
            Err(error) => engine.history_failure = Some(EngineError::Archive(error.to_string())),
        }
        match store.start_engine_scratch() {
            Ok((scratch, index)) => {
                engine.scratch = Some(scratch);
                engine.block_claim_index = Some(Arc::new(index));
            }
            Err(error) => engine.history_failure = Some(EngineError::Archive(error.to_string())),
        }
        engine.archive_store = Some(Arc::new(store));
        engine
    }

    pub(crate) fn runtime_authority(&self) -> &EngineAuthority {
        &self.runtime_authority
    }

    /// Open the enrolled projection capabilities without replaying non-empty
    /// operational history.
    ///
    /// A non-empty operational engine remains recovery-gated. Production
    /// startup should normally use [`Self::open_enrolled_projection`], which
    /// does not expose the engine until complete immutable history has been
    /// authenticated and pending projection work has been reconciled.
    pub fn with_enrolled_projection(
        store: ObjectStore,
        lineage_digest: LineageDigest,
        catalog_document_id: DocumentId,
        graph: &Graph,
        receipts: &ProjectionReceiptStore,
    ) -> Self {
        let workspace_id = store.workspace_id();
        let endpoint = receipts.endpoint_binding();
        let receipt_store_id = receipts.store_id();
        let enrollment_error = if receipts.workspace_id() != workspace_id {
            Some("projection receipt workspace does not match archive workspace".to_owned())
        } else if endpoint.is_none() {
            Some("projection receipt namespace has no endpoint enrollment".to_owned())
        } else {
            match graph.canonical_resource_id() {
                Ok(graph_resource_id)
                    if Some(graph_resource_id)
                        == endpoint.map(|binding| binding.graph_resource_id) =>
                {
                    None
                }
                Ok(_) => {
                    Some("projection receipt enrollment does not match graph capability".to_owned())
                }
                Err(error) => Some(format!(
                    "projection graph capability identity could not be verified: {error}"
                )),
            }
        };
        if let Some(error) = enrollment_error {
            return Self::failed_archive_open(
                store,
                lineage_digest,
                catalog_document_id,
                EngineError::Archive(error),
            );
        }
        let binding = ProjectionStorageBinding {
            endpoint: endpoint.expect("validated enrolled endpoint"),
            receipt_store_id,
        };
        match store.seal_enrolled_projection(binding) {
            Ok(open) => {
                Self::with_archive_store_for_endpoint(open, lineage_digest, catalog_document_id)
            }
            Err((store, error)) => Self::failed_archive_open(
                store,
                lineage_digest,
                catalog_document_id,
                EngineError::Archive(error.to_string()),
            ),
        }
    }

    /// Open an enrolled projection engine and complete its startup recovery.
    ///
    /// `committed_manifests` must be the caller's complete current manifest
    /// enumeration for `store`. Recovery reopens and authenticates every batch
    /// from the immutable archive; the supplied values select the bounded set
    /// to replay and do not themselves grant authority. Operational non-empty
    /// history remains inaccessible until replay coverage, durable bindings,
    /// and the reference catalog root all validate. Terminal authority is
    /// restored directly and never enters operational replay.
    pub fn open_enrolled_projection(
        store: ObjectStore,
        lineage_digest: LineageDigest,
        catalog_document_id: DocumentId,
        graph: &Graph,
        receipts: &ProjectionReceiptStore,
        committed_manifests: &[OperationBatch],
    ) -> Result<(Self, Vec<StageOutcome>), EngineError> {
        let mut engine = Self::with_enrolled_projection(
            store,
            lineage_digest,
            catalog_document_id,
            graph,
            receipts,
        );
        let outcomes = engine.complete_enrolled_projection_recovery(committed_manifests)?;
        Ok((engine, outcomes))
    }

    pub(crate) fn with_archive_store_for_endpoint(
        open: super::object_store::EnrolledProjectionOpen,
        lineage_digest: LineageDigest,
        catalog_document_id: DocumentId,
    ) -> Self {
        let binding = open.binding();
        let endpoint = binding.endpoint;
        let (store, history, projection_work_index) = match open.into_runtime() {
            Ok(runtime) => runtime,
            Err((store, error)) => {
                return Self::failed_archive_open(
                    store,
                    lineage_digest,
                    catalog_document_id,
                    EngineError::Archive(error.to_string()),
                );
            }
        };
        let history_current = history.current_with_binding();
        let work_current = projection_work_index.validate_runtime_open();
        if let Err(error) = &history_current {
            return Self::failed_archive_open(
                store,
                lineage_digest,
                catalog_document_id,
                EngineError::Archive(error.to_string()),
            );
        }
        if let Err(error) = &work_current {
            return Self::failed_archive_open(
                store,
                lineage_digest,
                catalog_document_id,
                EngineError::ProjectionWork(error.to_string()),
            );
        }
        let mut engine = Self::with_archive_store(store, lineage_digest, catalog_document_id);
        engine.durable_authority_mode = DurableAuthorityMode::EnrolledRequired;
        // An enrolled runtime may use the persistent page-name index only
        // after the authenticated history root and its latest record prove the
        // exact same typed binding.
        let page_name_index = engine.page_name_index.take();
        match history_current {
            Ok((generation, root, latest_batch_id, binding)) => {
                engine.history_generation = generation;
                engine.history_root = root;
                engine.history_store = Some(Arc::new(history));
                if binding.portable_path_key_version != super::PORTABLE_PATH_KEY_VERSION {
                    engine.history_failure = Some(EngineError::Archive(
                        "durable history portable-path key version mismatch".into(),
                    ));
                } else {
                    let portable_root =
                        PortablePathIndexRoot::from_digest(binding.portable_path_root);
                    match engine
                        .portable_path_index
                        .as_ref()
                        .ok_or_else(|| {
                            EngineError::Archive(
                                "durable history has no portable-path index".into(),
                            )
                        })
                        .and_then(|index| {
                            index
                                .validate_root(portable_root)
                                .map_err(|error| EngineError::Archive(error.to_string()))
                        }) {
                        Ok(()) => engine.portable_path_root = portable_root,
                        Err(error) => engine.history_failure = Some(error),
                    }
                }
                if let Some(terminal) = binding.terminal_evidence {
                    engine.fatal_handle = Some(FatalEvidenceHandle {
                        conflict_root: terminal.conflict_root,
                        conflicting_block_count: terminal.conflict_count,
                        claim_count: terminal.participant_count,
                        canonical_digest: terminal.canonical_digest,
                    });
                }
                engine.portable_path_conflicts = binding
                    .portable_path_conflicts
                    .iter()
                    .cloned()
                    .map(|conflict| (conflict.key_digest(), conflict))
                    .collect();
                if !engine.portable_path_conflicts.is_empty() {
                    let expected = portable_path_evidence_handle(&engine.portable_path_conflicts);
                    if engine.fatal_handle != Some(expected) {
                        engine.history_failure = Some(EngineError::Archive(
                            "durable portable-path evidence binding mismatch".into(),
                        ));
                    }
                }
                let page_name_proof = (|| {
                    binding
                        .page_names
                        .validate()
                        .map_err(|error| EngineError::Archive(error.to_string()))?;
                    let index = page_name_index.as_ref().ok_or_else(|| {
                        EngineError::Archive(
                            "durable history has no page-name ownership index".into(),
                        )
                    })?;
                    index
                        .validate_root(&binding.page_names.ownership_root)
                        .map_err(|error| EngineError::Archive(error.to_string()))?;
                    match (generation, latest_batch_id) {
                        (0, None) => {
                            if binding.page_names
                                != super::object_store::PageNameDurableBinding::empty()
                            {
                                return Err(EngineError::Archive(
                                    "empty durable history has non-empty page-name authority"
                                        .into(),
                                ));
                            }
                        }
                        (0, Some(_)) | (_, None) => {
                            return Err(EngineError::Archive(
                                "durable page-name authority has no latest history record".into(),
                            ));
                        }
                        (_, Some(latest_batch_id)) => {
                            let bytes = engine
                                .history_store
                                .as_ref()
                                .expect("history store installed before page-name proof")
                                .lookup(root, latest_batch_id)
                                .map_err(|error| EngineError::Archive(error.to_string()))?
                                .ok_or_else(|| {
                                    EngineError::Archive(
                                        "durable page-name authority latest record is absent"
                                            .into(),
                                    )
                                })?;
                            engine
                                .history_store
                                .as_ref()
                                .expect("history store installed before page-name proof")
                                .note_history_decode();
                            let record = decode_history_record(latest_batch_id, &bytes)?;
                            engine.validate_record_catalog_transition(&record)?;
                            if record.generation != generation
                                || history_record_binding(&record) != binding
                                || (!record.page_names.conflicts.is_empty()
                                    && !matches!(record.status, ArchiveStatus::Quarantined))
                            {
                                return Err(EngineError::Archive(
                                    "durable page-name record/root binding mismatch".into(),
                                ));
                            }
                            engine
                                .logseq_claim_index
                                .as_ref()
                                .ok_or_else(|| {
                                    EngineError::Archive(
                                        "durable history has no external UUID-claim index".into(),
                                    )
                                })?
                                .validate_root(record.logseq_claim_root)
                                .map_err(|error| EngineError::Archive(error.to_string()))?;
                            record
                                .reference_catalog_root
                                .validate_bound(
                                    &record.reference_catalog_policy,
                                    &record.page_names.ownership_root,
                                    record.logseq_claim_root.digest(),
                                )
                                .map_err(|error| EngineError::Archive(error.to_string()))?;
                            engine.logseq_claim_root = record.logseq_claim_root;
                            let reference_store =
                                engine.reference_catalog.store_handle().ok_or_else(|| {
                                    EngineError::Archive(
                                        "durable history has no reference catalog store".into(),
                                    )
                                })?;
                            engine.reference_catalog =
                                ReferenceCatalogStateV2::restore_recovery_required(
                                    record.reference_catalog_policy,
                                    record.reference_catalog_root,
                                    &record.page_names.ownership_root,
                                    record.logseq_claim_root.digest(),
                                    reference_store,
                                )
                                .map_err(|error| EngineError::Archive(error.to_string()))?;
                        }
                    }
                    Ok(())
                })();
                match page_name_proof {
                    Ok(()) => {
                        engine.page_name_root = binding.page_names.ownership_root.clone();
                        engine.page_name_conflicts = binding
                            .page_names
                            .conflicts
                            .iter()
                            .map(|evidence| {
                                evidence
                                    .digest()
                                    .map(|digest| (digest, evidence.clone()))
                                    .map_err(|error| EngineError::Archive(error.to_string()))
                            })
                            .collect::<Result<_, _>>()
                            .unwrap_or_else(|error| {
                                engine.history_failure = Some(error);
                                BTreeMap::new()
                            });
                        if engine.history_failure.is_none() {
                            engine.page_name_index = page_name_index;
                        }
                    }
                    Err(error) => engine.history_failure = Some(error),
                }
            }
            Err(error) => engine.history_failure = Some(EngineError::Archive(error.to_string())),
        }
        if engine.history_failure.is_none() {
            engine.projection_endpoint = Some(endpoint);
            engine.projection_receipt_store_id = Some(binding.receipt_store_id);
            engine.projection_work_index = Some(Arc::new(projection_work_index));
            if engine.fatal_handle.is_none()
                && engine.page_name_conflicts.is_empty()
                && engine.reference_catalog.ensure_ready().is_ok()
            {
                if let Err(error) = engine.reconcile_pending_projection_work(None) {
                    engine.history_failure = Some(error);
                }
            }
        }
        engine
    }

    fn failed_archive_open(
        store: ObjectStore,
        lineage_digest: LineageDigest,
        catalog_document_id: DocumentId,
        error: EngineError,
    ) -> Self {
        let workspace_id = store.workspace_id();
        let mut engine = Self::new(workspace_id, lineage_digest, catalog_document_id);
        engine.archive_store = Some(Arc::new(store));
        engine.history_failure = Some(error);
        engine.durable_authority_mode = DurableAuthorityMode::EnrolledRequired;
        engine
    }

    fn complete_enrolled_projection_recovery(
        &mut self,
        committed_manifests: &[OperationBatch],
    ) -> Result<Vec<StageOutcome>, EngineError> {
        if let Some(error) = &self.history_failure {
            return Err(error.clone());
        }
        if !matches!(self.workspace_status(), WorkspaceStatus::Operational) {
            return Ok(Vec::new());
        }
        match self.reference_catalog.ensure_ready() {
            Ok(()) => return Ok(Vec::new()),
            Err(ReferenceCatalogError::RecoveryRequired) => {}
            Err(error) => return Err(EngineError::ReferenceCatalog(error.to_string())),
        }

        self.prepare_operational_recovery_replay()?;
        let mut outcomes = Vec::with_capacity(committed_manifests.len());
        for manifest in committed_manifests {
            let outcome = self.stage_archive_batch_for_recovery(manifest.batch_id())?;
            if let Some(error) = &self.history_failure {
                return Err(error.clone());
            }
            outcomes.push(outcome);
        }
        self.finish_operational_recovery_replay()?;
        Ok(outcomes)
    }

    /// Rebuild every run-local derived structure from the retained
    /// authenticated durable roots, without replaying immutable history.
    ///
    /// This is the same-process engine-reconstruction seam. Nothing derived is
    /// carried across: hot archive caches, statuses, visible CRDT documents,
    /// point caches, and every ephemeral index candidate are discarded. Only
    /// the retained capabilities and their authenticated roots survive — in
    /// particular the scratch roots, which are the sole continuation authority
    /// for point-paged dependency registration and dependent fanout.
    ///
    /// The runtime authority is carried so a retained same-process `Graph`
    /// handoff, tail overlay, and SQLite frontier keep their exact enrollment
    /// and resource bindings. This deliberately does not claim process-restart
    /// writer exclusion: the managed-text latch is still process-local, and
    /// persisted enrollment owns reconstructing it before writer admission.
    #[allow(dead_code)] // activated only by the later persisted-enrollment packet
    pub(crate) fn reconstruct_run_local_state(&mut self) -> Result<(), EngineError> {
        if self.scratch.is_none() {
            return Err(EngineError::Archive(
                "engine reconstruction requires an authenticated run-local scratch".into(),
            ));
        }
        if self.authenticated_history_replay {
            return Err(EngineError::Archive(
                "engine reconstruction cannot interrupt an authenticated history replay".into(),
            ));
        }
        let mut rebuilt = Self::new(
            self.workspace_id,
            self.lineage_digest,
            self.catalog_document_id,
        );
        rebuilt.runtime_authority = self.runtime_authority.clone();
        // The reference catalog root and its attached durable store are
        // authenticated authority, not a run-local derivative, so they move
        // across reconstruction unchanged.
        std::mem::swap(&mut rebuilt.reference_catalog, &mut self.reference_catalog);
        rebuilt.archive_store = self.archive_store.take();
        rebuilt.projection_endpoint = self.projection_endpoint;
        rebuilt.projection_receipt_store_id = self.projection_receipt_store_id;
        rebuilt.projection_work_index = self.projection_work_index.take();
        rebuilt.scratch = self.scratch.take();
        rebuilt.scratch_roots = std::mem::take(&mut self.scratch_roots);
        rebuilt.history_store = self.history_store.take();
        rebuilt.history_generation = self.history_generation;
        rebuilt.history_root = self.history_root;
        rebuilt.history_failure = self.history_failure.clone();
        rebuilt.durable_authority_mode = self.durable_authority_mode;
        rebuilt.block_claim_index = self.block_claim_index.take();
        rebuilt.block_claim_root = self.block_claim_root.clone();
        rebuilt.logseq_claim_index = self.logseq_claim_index.take();
        rebuilt.logseq_claim_root = self.logseq_claim_root;
        rebuilt.portable_path_index = self.portable_path_index.take();
        rebuilt.portable_path_root = self.portable_path_root;
        rebuilt.portable_path_conflicts = std::mem::take(&mut self.portable_path_conflicts);
        rebuilt.page_name_index = self.page_name_index.take();
        rebuilt.page_name_root = self.page_name_root.clone();
        rebuilt.page_name_conflicts = std::mem::take(&mut self.page_name_conflicts);
        rebuilt.accepted_frontier_root = self.accepted_frontier_root.clone();
        rebuilt.next_acceptance_sequence = self.next_acceptance_sequence;
        rebuilt.current_path_catalog = self.current_path_catalog.clone();
        rebuilt.fatal_evidence = self.fatal_evidence.clone();
        // Telemetry is observational rather than continuation authority; keep
        // cumulative work accounting across the reconstructed journey.
        rebuilt.history_work.set(self.history_work.get());
        *self = rebuilt;
        Ok(())
    }

    /// Reset only reconstructible run-local state before replaying an
    /// operational enrolled archive. The enrolled history, projection, index,
    /// archive, and scratch capabilities remain attached; replay recomputes
    /// their roots from the immutable batches and validates each already
    /// authenticated final record instead of publishing it again.
    pub(crate) fn prepare_operational_recovery_replay(&mut self) -> Result<(), EngineError> {
        if !matches!(self.workspace_status(), WorkspaceStatus::Operational) {
            return Err(EngineError::Archive(
                "terminal enrolled authority cannot enter operational recovery replay".into(),
            ));
        }
        self.verify_current_durable_page_name_authority()?;

        let reference_policy = self.reference_catalog.policy().clone();
        let mut replay = Self::new(
            self.workspace_id,
            self.lineage_digest,
            self.catalog_document_id,
        );
        replay.runtime_authority = self.runtime_authority.clone();
        replay.configure_reference_catalog_policy(reference_policy)?;
        replay.archive_store = self.archive_store.take();
        replay.projection_endpoint = self.projection_endpoint;
        replay.projection_receipt_store_id = self.projection_receipt_store_id;
        replay.projection_work_index = self.projection_work_index.take();
        replay.scratch = self.scratch.take();
        replay.history_store = self.history_store.take();
        replay.history_generation = self.history_generation;
        replay.history_root = self.history_root;
        replay.durable_authority_mode = self.durable_authority_mode;
        replay.authenticated_history_replay = true;
        replay.block_claim_index = self.block_claim_index.take();
        replay.logseq_claim_index = self.logseq_claim_index.take();
        replay.portable_path_index = self.portable_path_index.take();
        replay.page_name_index = self.page_name_index.take();
        if let Some(store) = replay.archive_store.as_ref() {
            let catalog = store
                .open_reference_catalog()
                .map_err(|error| EngineError::Archive(error.to_string()))?;
            replay
                .reference_catalog
                .attach_store(Arc::new(catalog))
                .map_err(|error| EngineError::ReferenceCatalog(error.to_string()))?;
        }
        *self = replay;
        Ok(())
    }

    pub(crate) fn finish_operational_recovery_replay(&mut self) -> Result<(), EngineError> {
        if !self.authenticated_history_replay {
            return Err(EngineError::Archive(
                "operational recovery finish requires an active authenticated history replay"
                    .into(),
            ));
        }
        let replayed_records =
            u64::try_from(self.authenticated_replayed_batches.len()).map_err(|_| {
                EngineError::Archive(
                    "authenticated recovery replay record count exceeds durable generation range"
                        .into(),
                )
            })?;
        // Durable history generation advances exactly once for each new
        // BatchId record. This set gains a BatchId only after either its
        // current-root record matched every authenticated binding or recovery
        // durably finalized that exact manifest. Equal unique counts therefore
        // prove coverage of every current durable final record without a
        // graph-sized finish scan.
        if replayed_records != self.history_generation {
            return Err(EngineError::Archive(format!(
                "authenticated recovery replay covered {replayed_records} of {} durable final history records",
                self.history_generation
            )));
        }
        if self
            .authenticated_replayed_generations
            .keys()
            .copied()
            .ne(1..=self.history_generation)
        {
            return Err(EngineError::Archive(
                "authenticated recovery replay history generations are incomplete or duplicated"
                    .into(),
            ));
        }
        self.verify_current_durable_page_name_authority()?;
        let history_transition = self.authenticated_projection_history_transition()?;
        self.reference_catalog
            .finish_recovery()
            .map_err(|error| EngineError::ReferenceCatalog(error.to_string()))?;
        if self.fatal_handle.is_none() && self.page_name_conflicts.is_empty() {
            self.reconcile_pending_projection_work(history_transition)?;
        }
        self.authenticated_history_replay = false;
        Ok(())
    }

    pub(crate) fn enrolled_projection_runtime(
        &self,
    ) -> Result<(Arc<ObjectStore>, Arc<ProjectionWorkIndex>), EngineError> {
        self.ensure_not_blocked()?;
        self.reference_catalog
            .ensure_ready()
            .map_err(|error| EngineError::ReferenceCatalog(error.to_string()))?;
        if self.authenticated_history_replay {
            return Err(EngineError::ProjectionWork(
                "projection runtime is unavailable during authenticated history replay".into(),
            ));
        }
        let archive = self.archive_store.as_ref().ok_or_else(|| {
            EngineError::ProjectionWork("engine has no enrolled projection archive".into())
        })?;
        let index = self.projection_work_index.as_ref().ok_or_else(|| {
            EngineError::ProjectionWork("engine has no enrolled projection work index".into())
        })?;
        let endpoint = self.projection_endpoint.ok_or_else(|| {
            EngineError::ProjectionWork("engine has no enrolled projection endpoint".into())
        })?;
        if archive.workspace_id() != self.workspace_id
            || index.workspace_id() != self.workspace_id
            || index.endpoint_id() != endpoint.endpoint_id
            || index.graph_resource_id() != endpoint.graph_resource_id
            || index.receipt_store_id()
                != self.projection_receipt_store_id.ok_or_else(|| {
                    EngineError::ProjectionWork(
                        "engine has no enrolled projection receipt store".into(),
                    )
                })?
        {
            return Err(EngineError::ProjectionWork(
                "engine-owned projection runtime binding mismatch".into(),
            ));
        }
        Ok((Arc::clone(archive), Arc::clone(index)))
    }

    pub fn projection_work_index(&self) -> Result<&ProjectionWorkIndex, EngineError> {
        self.ensure_not_blocked()?;
        self.projection_work_index.as_deref().ok_or_else(|| {
            EngineError::ProjectionWork("engine has no enrolled projection work index".into())
        })
    }

    pub const fn projection_endpoint_binding(&self) -> Option<ProjectionEndpointBinding> {
        self.projection_endpoint
    }

    pub(crate) const fn projection_receipt_store_id(
        &self,
    ) -> Option<super::ProjectionReceiptStoreId> {
        self.projection_receipt_store_id
    }

    pub const fn workspace_id(&self) -> WorkspaceId {
        self.workspace_id
    }

    pub const fn lineage_digest(&self) -> LineageDigest {
        self.lineage_digest
    }

    pub fn configure_reference_catalog_policy(
        &mut self,
        policy: ReferenceCatalogPolicyV1,
    ) -> Result<(), EngineError> {
        self.ensure_not_blocked()?;
        if self.next_acceptance_sequence != 0
            || self.history_generation != 0
            || self.reference_catalog.root().source_count() != 0
        {
            return Err(EngineError::ReferenceCatalog(
                "reference policy is immutable after the first accepted frontier".into(),
            ));
        }
        let reference_store = self.reference_catalog.store_handle();
        self.reference_catalog = ReferenceCatalogStateV2::empty(
            policy,
            &self.page_name_root,
            self.logseq_claim_root.digest(),
        )
        .map_err(|error| EngineError::ReferenceCatalog(error.to_string()))?;
        if let Some(store) = reference_store {
            self.reference_catalog
                .attach_store(store)
                .map_err(|error| EngineError::ReferenceCatalog(error.to_string()))?;
        }
        self.accepted_frontier_root =
            empty_accepted_frontier_root_with_catalog(self.reference_catalog.root().clone());
        self.current_path_catalog.accepted_frontier_root = self.accepted_frontier_root.clone();
        self.current_path_cursor_book.borrow_mut().active.clear();
        Ok(())
    }

    pub const fn catalog_document_id(&self) -> DocumentId {
        self.catalog_document_id
    }

    #[cfg(test)]
    fn record_replay_timing(&self, update: impl FnOnce(&mut ReplayTimingStats)) {
        let mut timing = self.replay_timing.get();
        update(&mut timing);
        self.replay_timing.set(timing);
    }

    #[cfg(test)]
    fn record_authenticated_exact_catalog_load(&self) {
        let mut loads = self.catalog_checkpoint_loads.get();
        loads.authenticated_exact = loads.authenticated_exact.saturating_add(1);
        self.catalog_checkpoint_loads.set(loads);
    }

    #[cfg(test)]
    fn record_current_catalog_load(&self, document_id: DocumentId) {
        if document_id != self.catalog_document_id {
            return;
        }
        let mut loads = self.catalog_checkpoint_loads.get();
        loads.current = loads.current.saturating_add(1);
        self.catalog_checkpoint_loads.set(loads);
    }

    #[cfg(test)]
    fn record_carried_reference_catalog_page(&self) {
        let mut observations = self.reference_source_observations.get();
        observations.carried_catalog_pages = observations.carried_catalog_pages.saturating_add(1);
        self.reference_source_observations.set(observations);
    }

    #[cfg(test)]
    fn record_carried_reference_shard(&self, origin: ValidatedReferenceSourceOrigin) {
        let mut observations = self.reference_source_observations.get();
        observations.carried_shards = observations.carried_shards.saturating_add(1);
        match origin {
            ValidatedReferenceSourceOrigin::NewShard => {
                observations.carried_new_shards = observations.carried_new_shards.saturating_add(1);
            }
            ValidatedReferenceSourceOrigin::AfterSnapshot => {
                observations.carried_after_snapshots =
                    observations.carried_after_snapshots.saturating_add(1);
            }
        }
        self.reference_source_observations.set(observations);
    }

    #[cfg(test)]
    fn record_reference_source_fallback(&self) {
        let mut observations = self.reference_source_observations.get();
        observations.fallback_document_reconstructions = observations
            .fallback_document_reconstructions
            .saturating_add(1);
        self.reference_source_observations.set(observations);
    }

    pub fn instrumentation(&self) -> EngineInstrumentation {
        let work = self.history_work.get();
        let logseq_claims = self
            .logseq_claim_index
            .as_ref()
            .map(|index| index.stats())
            .unwrap_or_default();
        let portable_paths = self
            .portable_path_index
            .as_ref()
            .map(|index| index.stats())
            .unwrap_or_default();
        let scratch = self
            .scratch
            .as_ref()
            .map(|store| store.stats())
            .unwrap_or_default();
        let projection_work = self
            .projection_work_index
            .as_ref()
            .map(|index| index.stats())
            .unwrap_or_default();
        EngineInstrumentation {
            prepare_transactions: work.prepare_transactions,
            prepare_document_head_visits: work.prepare_document_head_visits,
            author_snapshot_clones: work.author_snapshot_clones,
            author_snapshot_clone_ops: work.author_snapshot_clone_ops,
            stage_snapshot_clones: work.stage_snapshot_clones,
            stage_snapshot_clone_ops: work.stage_snapshot_clone_ops,
            stage_structural_buffer_reuses: work.stage_structural_buffer_reuses,
            drain_candidate_visits: work.drain_candidate_visits,
            dependency_status_lookups: work.dependency_status_lookups,
            document_point_reads: work.document_point_reads,
            state_page_bytes_read: work.state_page_bytes_read,
            state_page_bytes_written: work.state_page_bytes_written,
            wait_edge_visits: work.wait_edge_visits,
            ready_queue_residency: work.ready_queue_residency,
            external_flushes: work.external_flushes,
            external_point_reads: work.external_point_reads,
            external_range_scans: work.external_range_scans,
            external_history_page_reads: work.external_history_page_reads,
            external_history_blob_reads: work.external_history_blob_reads,
            recovery_history_record_reads: work.recovery_history_record_reads,
            projection_reconciliation_history_record_reads: work
                .projection_reconciliation_history_record_reads,
            ancestry_traversals: work.ancestry_traversals,
            dependency_head_visits: work.dependency_head_visits,
            causal_accumulator_parent_points: work.causal_accumulator_parent_points,
            causal_accumulator_materialized_points: work.causal_accumulator_materialized_points,
            staged_record_max_bytes: work.staged_record_max_bytes,
            weighted_work_prepaid: work.weighted_work_prepaid,
            scratch_page_reads: scratch.page_reads,
            scratch_page_bytes_read: scratch.page_bytes_read,
            scratch_max_page_bytes_read: scratch.max_page_bytes_read,
            scratch_syncs: scratch.scratch_syncs,
            stale_scratch_runs_reclaimed: scratch.stale_runs_reclaimed,
            live_scratch_runs_skipped: scratch.live_runs_skipped,
            batch_status_hot_entries: self.statuses.len(),
            ready_payload_hot_entries: self.archive.len(),
            document_hot_entries: self
                .visible_documents
                .keys()
                .chain(self.terminal_documents.keys())
                .copied()
                .collect::<BTreeSet<_>>()
                .len(),
            conflict_hot_entries: self
                .fatal_evidence
                .as_ref()
                .map(|evidence| evidence.conflicts().len())
                .unwrap_or(0),
            block_claim_hot_entries: self.ephemeral_block_claims.len(),
            logseq_claim_hot_entries: self.ephemeral_logseq_claims.len(),
            logseq_claim_index_reads: logseq_claims.reads,
            logseq_claim_index_writes: logseq_claims.writes,
            portable_path_index_reads: portable_paths.reads,
            portable_path_index_writes: portable_paths.writes,
            portable_path_index_bytes_read: portable_paths.bytes_read,
            portable_path_index_bytes_written: portable_paths.bytes_written,
            projection_work_node_reads: projection_work.node_reads,
            projection_work_root_reads: projection_work.root_reads,
            projection_work_prepared_reads: projection_work.prepared_reads,
            projection_pending_entries_read: projection_work.pending_entries_read,
            projection_preflight_nodes: projection_work.preflight_nodes,
            projection_preflight_records: projection_work.preflight_records,
            projection_preflight_roots: projection_work.preflight_roots,
            projection_preflight_bytes: projection_work.preflight_bytes,
            block_claim_validation_nanos: work.block_claim_validation_nanos,
            block_claim_lookup_nanos: work.block_claim_lookup_nanos,
            block_claim_encode_nanos: work.block_claim_encode_nanos,
            block_claim_insert_nanos: work.block_claim_insert_nanos,
            store: self
                .archive_store
                .as_ref()
                .map(|store| store.instrumentation())
                .unwrap_or_default(),
        }
    }

    /// One atomic diagnostic view. Accepted batches remain historical facts
    /// even when `workspace` is terminally blocked.
    pub fn status(&self) -> EngineStatus {
        let active = self
            .statuses
            .iter()
            .map(|(batch_id, status)| {
                let binding = self.durable_history_binding();
                new_history_record(
                    self.history_generation.saturating_add(1),
                    *batch_id,
                    self.archive_fingerprints[batch_id],
                    binding,
                    self.logseq_claim_root,
                    self.reference_catalog.policy().clone(),
                    self.reference_catalog.root().clone(),
                    status.clone(),
                )
            })
            .collect();
        let history_source = match (&self.history_failure, &self.scratch, &self.history_store) {
            (Some(error), _, _) => StatusHistorySource::Failed(error.clone()),
            (None, Some(scratch_store), Some(history_store)) => {
                StatusHistorySource::DurableAndScratch {
                    history_store: Arc::clone(history_store),
                    catalog_store: self.reference_catalog.store_handle(),
                    through_generation: self.history_generation,
                    history_root: self.history_root,
                    scratch_store: Arc::clone(scratch_store),
                    scratch_roots: self.scratch_roots.clone(),
                }
            }
            (None, Some(store), None) => StatusHistorySource::Scratch {
                store: Arc::clone(store),
                roots: self.scratch_roots.clone(),
            },
            (None, None, Some(store)) => StatusHistorySource::Cold {
                store: Arc::clone(store),
                catalog_store: self.reference_catalog.store_handle(),
                through_generation: self.history_generation,
                history_root: self.history_root,
                active,
            },
            (None, None, None) => StatusHistorySource::Inline(status_history_from_records(active)),
        };
        EngineStatus {
            history_source,
            history: OnceLock::new(),
            workspace: self.workspace_status(),
        }
    }

    /// Return the incrementally maintained complete accepted frontier.
    pub fn exact_frontier(&self) -> Result<FrontierV2, EngineError> {
        self.ensure_not_blocked()?;
        if let Some(store) = &self.scratch {
            return materialize_accepted_frontier(
                store,
                &self.scratch_roots.accepted_frontier_root,
            );
        }
        FrontierV2::new(self.accepted_frontier.values().cloned().collect())
            .map_err(EngineError::from)
    }

    pub fn accepted_frontier_root(&self) -> Result<AcceptedFrontierRoot, EngineError> {
        self.ensure_not_blocked()?;
        validate_accepted_frontier_root(&self.accepted_frontier_root)?;
        Ok(self.accepted_frontier_root.clone())
    }

    /// Start an opaque, bounded cursor over the current accepted live page
    /// paths. The cursor is run-local: it binds this exact engine capability,
    /// workspace, history identity, schema, and accepted frontier.
    #[allow(dead_code)]
    pub(crate) fn begin_current_path_cursor(
        &self,
    ) -> Result<CurrentPathCatalogCursor, EngineError> {
        self.begin_point_operation();
        let binding = self.current_path_cursor_binding()?;
        self.mint_current_path_cursor(binding, None)
    }

    /// Consume one opaque cursor and return the next bounded page. Each token
    /// is single-use, so an exact final page terminates without re-reading any
    /// previously returned row.
    #[allow(dead_code)]
    pub(crate) fn current_path_cursor_page(
        &self,
        cursor: CurrentPathCatalogCursor,
        limit: usize,
    ) -> Result<CurrentPathCatalogPage, EngineError> {
        if limit == 0 || limit > MAX_CURRENT_PATH_CURSOR_PAGE_ROWS {
            return Err(EngineError::Archive(format!(
                "current-path cursor page limit {limit} is outside 1..={MAX_CURRENT_PATH_CURSOR_PAGE_ROWS}"
            )));
        }
        self.validate_current_path_cursor_binding(&cursor)?;
        let continuation = self.take_current_path_cursor(cursor)?;
        let mut rows = Vec::new();
        rows.try_reserve_exact(limit).map_err(|error| {
            EngineError::Archive(format!(
                "current-path cursor page allocation failed before use: {error}"
            ))
        })?;
        let Some(store) = self.scratch.as_ref() else {
            debug_assert_eq!(self.current_path_catalog.root.count(), 0);
            return Ok(CurrentPathCatalogPage { rows, next: None });
        };
        let mut range = store
            .authenticated_catalog_cursor(
                &self.current_path_catalog.root,
                continuation
                    .after
                    .map(|page_id| page_id.as_uuid().into_bytes()),
            )
            .map_err(|error| EngineError::Archive(error.to_string()))?;
        let mut page_bytes = 0_usize;
        let mut last = None;
        while rows.len() < limit {
            let Some((key, encoded)) = range
                .next_entry()
                .map_err(|error| EngineError::Archive(error.to_string()))?
            else {
                break;
            };
            let page_id = PageId::from_uuid(Uuid::from_bytes(key));
            let stored = decode_current_path_catalog_row(&encoded)?;
            let row = CurrentPathCatalogRow {
                page_id,
                path: stored.path,
                kind: stored.kind,
            };
            let path_bytes = row.path.as_str().len();
            if path_bytes > MAX_CURRENT_PATH_CURSOR_PATH_BYTES {
                return Err(EngineError::Archive(format!(
                    "current-path cursor path for {page_id} is {path_bytes} bytes, bound {MAX_CURRENT_PATH_CURSOR_PATH_BYTES}"
                )));
            }
            self.validate_current_path_catalog_row(&row)?;
            page_bytes = page_bytes.checked_add(path_bytes).ok_or_else(|| {
                EngineError::Archive("current-path cursor page-byte counter overflow".into())
            })?;
            if page_bytes > MAX_CURRENT_PATH_CURSOR_PAGE_BYTES {
                return Err(EngineError::Archive(format!(
                    "current-path cursor page bytes {page_bytes} exceed bound {MAX_CURRENT_PATH_CURSOR_PAGE_BYTES}"
                )));
            }
            rows.push(row);
            last = Some(page_id);
        }
        let has_more = match range
            .next_entry()
            .map_err(|error| EngineError::Archive(error.to_string()))?
        {
            Some((key, encoded)) => {
                let stored = decode_current_path_catalog_row(&encoded)?;
                self.validate_current_path_catalog_row(&CurrentPathCatalogRow {
                    page_id: PageId::from_uuid(Uuid::from_bytes(key)),
                    path: stored.path,
                    kind: stored.kind,
                })?;
                true
            }
            None => false,
        };
        #[cfg(test)]
        self.current_path_cursor_rows_visited.set(
            self.current_path_cursor_rows_visited
                .get()
                .saturating_add(range.visited()),
        );
        let next = has_more
            .then(|| {
                self.mint_current_path_cursor(
                    continuation.binding,
                    Some(last.expect("a nonempty bounded page has a continuation key")),
                )
            })
            .transpose()?;
        Ok(CurrentPathCatalogPage { rows, next })
    }

    fn current_path_cursor_binding(&self) -> Result<CurrentPathCursorBinding, EngineError> {
        self.ensure_not_blocked()?;
        if self.authenticated_history_replay {
            return Err(EngineError::Archive(
                "current-path cursor is unavailable during authenticated history replay".into(),
            ));
        }
        validate_accepted_frontier_root(&self.accepted_frontier_root)?;
        if self.current_path_catalog.accepted_frontier_root != self.accepted_frontier_root {
            return Err(EngineError::Archive(
                "current-path catalog is not bound to the current accepted frontier".into(),
            ));
        }
        if !self.current_path_catalog.available {
            return Err(EngineError::Archive(
                "current-path catalog authenticated authority is unavailable".into(),
            ));
        }
        if self.current_path_catalog.root.count() > MAX_DOCUMENT_ENTRIES as u64 {
            return Err(EngineError::Archive(
                "current-path catalog entry bound exceeded".into(),
            ));
        }
        if self.scratch.is_none() && self.current_path_catalog.root.count() != 0 {
            return Err(EngineError::Archive(
                "current-path catalog has no authenticated scratch capability".into(),
            ));
        }
        Ok(CurrentPathCursorBinding {
            schema_version: CURRENT_PATH_CURSOR_SCHEMA_VERSION,
            catalog_page_state_schema_version: super::CATALOG_PAGE_STATE_SCHEMA_VERSION,
            engine_history_schema_version: ENGINE_HISTORY_SCHEMA_VERSION,
            workspace_id: self.workspace_id,
            lineage_digest: self.lineage_digest,
            accepted_frontier_root: self.accepted_frontier_root.clone(),
            history_generation: self.history_generation,
            history_root: self.history_root,
            catalog_root_digest: self.current_path_catalog.root.root_digest(),
            catalog_row_count: self.current_path_catalog.root.count(),
        })
    }

    fn validate_current_path_cursor_binding(
        &self,
        cursor: &CurrentPathCatalogCursor,
    ) -> Result<(), EngineError> {
        if cursor.binding.schema_version != CURRENT_PATH_CURSOR_SCHEMA_VERSION
            || cursor.binding.catalog_page_state_schema_version
                != super::CATALOG_PAGE_STATE_SCHEMA_VERSION
            || cursor.binding.engine_history_schema_version != ENGINE_HISTORY_SCHEMA_VERSION
        {
            return Err(EngineError::Archive(
                "current-path cursor schema binding is unsupported".into(),
            ));
        }
        if cursor.binding.workspace_id != self.workspace_id {
            return Err(EngineError::WorkspaceMismatch {
                expected: self.workspace_id,
                found: cursor.binding.workspace_id,
            });
        }
        if cursor.binding.lineage_digest != self.lineage_digest {
            return Err(EngineError::LineageMismatch {
                expected: self.lineage_digest,
                found: cursor.binding.lineage_digest,
            });
        }
        if !self.runtime_authority.matches(&cursor.runtime_authority) {
            return Err(EngineError::Archive(
                "current-path cursor belongs to another engine instance".into(),
            ));
        }
        let current = self.current_path_cursor_binding()?;
        if cursor.binding.accepted_frontier_root != current.accepted_frontier_root {
            return Err(EngineError::Archive(
                "current-path cursor accepted frontier is stale".into(),
            ));
        }
        if cursor.binding.history_generation != current.history_generation
            || cursor.binding.history_root != current.history_root
        {
            return Err(EngineError::Archive(
                "current-path cursor durable history identity is stale".into(),
            ));
        }
        if cursor.binding.catalog_root_digest != current.catalog_root_digest
            || cursor.binding.catalog_row_count != current.catalog_row_count
        {
            return Err(EngineError::Archive(
                "current-path cursor authenticated catalog root is stale".into(),
            ));
        }
        Ok(())
    }

    fn mint_current_path_cursor(
        &self,
        binding: CurrentPathCursorBinding,
        after: Option<PageId>,
    ) -> Result<CurrentPathCatalogCursor, EngineError> {
        let mut book = self.current_path_cursor_book.borrow_mut();
        if book.active.len() >= MAX_CURRENT_PATH_CURSORS {
            return Err(EngineError::Archive(format!(
                "current-path cursor count exceeds bound {MAX_CURRENT_PATH_CURSORS}"
            )));
        }
        let cursor_id = book.next_cursor_id;
        book.next_cursor_id = book.next_cursor_id.checked_add(1).ok_or_else(|| {
            EngineError::Archive("current-path cursor identifier overflow".into())
        })?;
        let nonce = book.next_nonce;
        book.next_nonce = book
            .next_nonce
            .checked_add(1)
            .ok_or_else(|| EngineError::Archive("current-path cursor nonce overflow".into()))?;
        book.active.insert(
            cursor_id,
            CurrentPathCursorState {
                binding: binding.clone(),
                after,
                nonce,
            },
        );
        Ok(CurrentPathCatalogCursor {
            runtime_authority: self.runtime_authority.clone(),
            binding,
            cursor_id,
            nonce,
        })
    }

    fn take_current_path_cursor(
        &self,
        cursor: CurrentPathCatalogCursor,
    ) -> Result<CurrentPathCursorState, EngineError> {
        let state = self
            .current_path_cursor_book
            .borrow_mut()
            .active
            .remove(&cursor.cursor_id)
            .ok_or_else(|| {
                EngineError::Archive("current-path cursor is stale or consumed".into())
            })?;
        if state.nonce != cursor.nonce || state.binding != cursor.binding {
            return Err(EngineError::Archive(
                "current-path cursor token authentication failed".into(),
            ));
        }
        Ok(state)
    }

    fn validate_current_path_catalog_row(
        &self,
        row: &CurrentPathCatalogRow,
    ) -> Result<(), EngineError> {
        let key = row.path.portable_key().digest();
        let records = self.portable_path_records_many(std::slice::from_ref(&key))?;
        let occupied = records.get(&key).and_then(PortablePathRecord::occupied);
        if occupied.is_none_or(|occupied| {
            occupied.page_id() != row.page_id || occupied.exact_path() != &row.path
        }) {
            return Err(EngineError::Archive(
                "current-path catalog row has missing, duplicate, or corrupt path authority".into(),
            ));
        }
        Ok(())
    }

    pub fn accepted_batch_count(&self) -> Result<u64, EngineError> {
        self.ensure_not_blocked()?;
        Ok(self.next_acceptance_sequence)
    }

    pub fn accepted_batch_id_at(&self, sequence: u64) -> Result<Option<BatchId>, EngineError> {
        Ok(self
            .accepted_batch_entry_at(sequence)?
            .map(|(batch_id, _)| batch_id))
    }

    pub(crate) fn accepted_batch_entry_at(
        &self,
        sequence: u64,
    ) -> Result<Option<(BatchId, Option<AcceptedBatchEvidence>)>, EngineError> {
        self.ensure_not_blocked()?;
        if sequence == 0 || sequence > self.next_acceptance_sequence {
            return Ok(None);
        }
        if let Some(store) = &self.scratch {
            return store
                .lookup_accepted_sequence(&self.scratch_roots.accepted_sequence_root, sequence)
                .map_err(|error| EngineError::Archive(error.to_string()))?
                .map(|entry| {
                    let evidence = decode_accepted_evidence(&entry.evidence)?;
                    if evidence.batch_id != entry.batch_id
                        || evidence.acceptance_sequence != sequence
                    {
                        return Err(EngineError::Archive(
                            "accepted sequence point entry is misbound".into(),
                        ));
                    }
                    Ok((entry.batch_id, Some(evidence)))
                })
                .transpose();
        }
        Ok(self
            .accepted_sequence
            .get(&sequence)
            .copied()
            .map(|batch_id| (batch_id, None)))
    }

    pub(crate) fn accepted_batch_cursor(&self) -> Result<AcceptedBatchCursor<'_>, EngineError> {
        self.ensure_not_blocked()?;
        if let Some(store) = &self.scratch {
            return Ok(AcceptedBatchCursor::Scratch(
                store
                    .accepted_sequence_cursor(&self.scratch_roots.accepted_sequence_root)
                    .map_err(|error| EngineError::Archive(error.to_string()))?,
            ));
        }
        Ok(AcceptedBatchCursor::Inline(self.accepted_sequence.iter()))
    }

    pub fn accepted_frontier_document(
        &self,
        root: &AcceptedFrontierRoot,
        document_id: DocumentId,
    ) -> Result<Option<DocumentDependencies>, EngineError> {
        self.ensure_not_blocked()?;
        validate_accepted_frontier_root(root)?;
        let Some(scratch_root) = &root.scratch_root else {
            if root == &self.accepted_frontier_root {
                return Ok(self.accepted_frontier.get(&document_id).cloned());
            }
            return Err(EngineError::Archive(
                "historical frontier point queries require store-backed accepted history".into(),
            ));
        };
        let store = self.scratch.as_ref().ok_or_else(|| {
            EngineError::Archive(
                "store-backed accepted frontier root has no authenticated scratch store".into(),
            )
        })?;
        let bytes = store
            .lookup(
                scratch_root,
                super::scratch_store::ScratchPageKind::AcceptedFrontier,
                document_id.as_uuid().as_bytes(),
            )
            .map_err(|error| EngineError::Archive(error.to_string()))?;
        bytes
            .map(|bytes| decode_accepted_document(document_id, &bytes))
            .transpose()
    }

    fn authenticate_accepted_frontier_root(
        &self,
        root: &AcceptedFrontierRoot,
    ) -> Result<(), EngineError> {
        self.ensure_not_blocked()?;
        validate_accepted_frontier_root(root)?;
        if root.acceptance_sequence() == 0 {
            if root != &AcceptedFrontierRoot::empty() {
                return Err(EngineError::Archive(
                    "requested empty accepted frontier is not canonical".into(),
                ));
            }
            return Ok(());
        }
        let (_, evidence) = self
            .accepted_batch_entry_at(root.acceptance_sequence())?
            .ok_or_else(|| {
                EngineError::Archive(format!(
                    "requested accepted frontier sequence {} is unavailable",
                    root.acceptance_sequence()
                ))
            })?;
        match evidence {
            Some(evidence) if evidence.post_frontier_root() == root => Ok(()),
            Some(_) => Err(EngineError::Archive(
                "requested accepted frontier root is not bound to accepted history".into(),
            )),
            None if root == &self.accepted_frontier_root => Ok(()),
            None => Err(EngineError::Archive(
                "historical frontier authentication requires store-backed accepted history".into(),
            )),
        }
    }

    fn load_document_at_accepted_frontier(
        &self,
        root: &AcceptedFrontierRoot,
        document_id: DocumentId,
    ) -> Result<Option<LoroDoc>, EngineError> {
        let Some(dependencies) = self.accepted_frontier_document(root, document_id)? else {
            return Ok(None);
        };
        let frontier = FrontierV2::new(vec![dependencies]).map_err(EngineError::from)?;
        let mut documents = self.reconstruct_projection_frontier(&frontier)?;
        documents
            .remove(&document_id)
            .ok_or(EngineError::MissingDocument(document_id))
            .map(Some)
    }

    pub(crate) fn materialize_page_at_accepted_root(
        &self,
        root: &AcceptedFrontierRoot,
        page_id: PageId,
    ) -> Result<Option<MaterializedPage>, EngineError> {
        self.begin_point_operation();
        self.authenticate_accepted_frontier_root(root)?;
        let reads_before = self.archive_read_stats();
        let Some(catalog) =
            self.load_document_at_accepted_frontier(root, self.catalog_document_id)?
        else {
            return Ok(None);
        };
        let Some(page_state) = validate_catalog_page(self.catalog_document_id, &catalog, page_id)?
        else {
            return Ok(None);
        };
        let PageState::Live {
            home_document_id: page_document_id,
            ..
        } = page_state
        else {
            return Ok(None);
        };
        let page_document = self
            .load_document_at_accepted_frontier(root, page_document_id)?
            .ok_or(EngineError::MissingDocument(page_document_id))?;
        validate_shard(self.catalog_document_id, page_document_id, &page_document)?;
        if shard_page_id(&page_document)? != Some(page_id) {
            return Err(EngineError::MalformedDocument {
                document_id: page_document_id,
                reason: "membership shard page identity mismatch".into(),
            });
        }
        let members = read_memberships(page_document_id, &page_document)?;
        let mut documents = BTreeMap::from([
            (self.catalog_document_id, catalog),
            (page_document_id, page_document),
        ]);
        for home_document_id in members
            .values()
            .map(|claim| claim.home_document_id)
            .collect::<BTreeSet<_>>()
        {
            if documents.contains_key(&home_document_id) {
                continue;
            }
            let home = self
                .load_document_at_accepted_frontier(root, home_document_id)?
                .ok_or(EngineError::MissingDocument(home_document_id))?;
            documents.insert(home_document_id, home);
        }
        let mut page = self.materialize_page_from_documents(page_id, &documents)?;
        let reads_after = self.archive_read_stats();
        page.stats.physical_manifest_reads = reads_after
            .manifest_reads
            .saturating_sub(reads_before.manifest_reads);
        page.stats.physical_object_reads = reads_after
            .object_reads
            .saturating_sub(reads_before.object_reads);
        Ok(Some(page))
    }

    /// Point lookup of immutable evidence bound when this batch became
    /// accepted. Store-backed engines authenticate the record from scratch
    /// state and cross-check its manifest fingerprint against batch history.
    pub fn accepted_batch_evidence(
        &self,
        batch_id: BatchId,
    ) -> Result<AcceptedBatchEvidence, EngineError> {
        self.begin_point_operation();
        self.ensure_not_blocked()?;
        let evidence = match self.archive_status(batch_id)? {
            Some(ArchiveStatus::Accepted { evidence, .. }) => evidence,
            _ => return Err(EngineError::MissingDependency(batch_id)),
        };
        let expected_fingerprint = if let Some(store) = &self.scratch {
            super::dependency_queue::lookup(store, &self.scratch_roots, batch_id)
                .map_err(|error| EngineError::Archive(error.to_string()))?
                .ok_or_else(|| {
                    EngineError::Archive(format!("accepted batch {batch_id} has no status history"))
                })?
                .manifest_fingerprint()
        } else {
            self.archive_fingerprints
                .get(&batch_id)
                .copied()
                .ok_or(EngineError::MissingDependency(batch_id))?
        };
        if evidence.manifest_fingerprint != expected_fingerprint {
            return Err(EngineError::Archive(format!(
                "accepted batch {batch_id} frontier evidence fingerprint mismatch"
            )));
        }
        validate_accepted_evidence(&evidence)?;
        Ok(evidence)
    }

    fn prepare_acceptance_evidence(
        &self,
        batch_id: BatchId,
        precomputed_event_binding_digest: Option<ContentDigest>,
        updates: &BTreeMap<DocumentId, CrdtUpdatePayload>,
        replacements: &BTreeMap<DocumentId, EngineDocument>,
        replacement_heads: &BTreeMap<DocumentId, BTreeSet<BatchId>>,
        candidate_roots: &ScratchRoots,
        reference_catalog_delta: &ReferenceCatalogDeltaV2,
    ) -> Result<
        (
            Option<BTreeMap<DocumentId, DocumentDependencies>>,
            AcceptedBatchEvidence,
            ScratchRoots,
        ),
        EngineError,
    > {
        let mut changed_documents = BTreeMap::new();
        for (document_id, replacement) in replacements {
            let mut heads = if let Some(heads) = replacement_heads.get(document_id) {
                heads.clone()
            } else {
                self.accepted_document_dependencies(*document_id)?
                    .map(|document| document.direct_dependency_heads().iter().copied().collect())
                    .unwrap_or_default()
            };
            for dependency in &updates[document_id].dependency_heads {
                heads.remove(dependency);
            }
            heads.insert(batch_id);
            let dependencies = DocumentDependencies::new(
                *document_id,
                canonical_peer_counters(&replacement.document().oplog_vv())?,
                heads.into_iter().collect(),
            )?;
            changed_documents.insert(*document_id, dependencies);
        }
        let mut roots = candidate_roots.clone();
        let acceptance_sequence = self
            .next_acceptance_sequence
            .checked_add(1)
            .ok_or_else(|| EngineError::Archive("acceptance sequence overflowed".into()))?;
        let prior_frontier_root = self.accepted_frontier_root.clone();
        let new_document_count = changed_documents.keys().try_fold(
            prior_frontier_root.document_count,
            |count, document_id| -> Result<u64, EngineError> {
                Ok(
                    if self.accepted_document_dependencies(*document_id)?.is_some() {
                        count
                    } else {
                        count.checked_add(1).ok_or_else(|| {
                            EngineError::Archive("accepted document count overflowed".into())
                        })?
                    },
                )
            },
        )?;
        let (post_documents, scratch_root, document_map_root_key, document_map_root_digest) =
            if let Some(store) = &self.scratch {
                let records = changed_documents
                    .iter()
                    .map(|(document_id, dependencies)| {
                        Ok((
                            document_id.as_uuid().as_bytes().to_vec(),
                            Some(encode_accepted_document(dependencies)?),
                        ))
                    })
                    .collect::<Result<BTreeMap<_, _>, EngineError>>()?;
                roots.accepted_frontier_root = store
                    .insert_many(
                        &roots.accepted_frontier_root,
                        super::scratch_store::ScratchPageKind::AcceptedFrontier,
                        &records,
                    )
                    .map_err(|error| EngineError::Archive(error.to_string()))?;
                for (document_id, dependencies) in &changed_documents {
                    let value_digest = ContentDigest::of(&encode_accepted_document(dependencies)?);
                    roots.accepted_document_map_root = store
                        .authenticated_map_upsert(
                            &roots.accepted_document_map_root,
                            document_id.as_uuid().into_bytes(),
                            value_digest,
                        )
                        .map_err(|error| EngineError::Archive(error.to_string()))?;
                }
                if roots.accepted_document_map_root.count() != new_document_count {
                    return Err(EngineError::Archive(
                        "authenticated document map count differs from accepted frontier".into(),
                    ));
                }
                (
                    None,
                    Some(roots.accepted_frontier_root.clone()),
                    roots.accepted_document_map_root.root_key(),
                    roots.accepted_document_map_root.root_digest(),
                )
            } else {
                let mut post_documents = self.accepted_frontier.clone();
                post_documents.extend(changed_documents.clone());
                let all_documents = post_documents.values().cloned().collect::<Vec<_>>();
                let (root_key, root_digest) = authenticated_document_map_root(&all_documents)?;
                (Some(post_documents), None, root_key, root_digest)
            };
        let manifest_fingerprint = self
            .archive_fingerprints
            .get(&batch_id)
            .copied()
            .ok_or(EngineError::MissingDependency(batch_id))?;
        let manifest = self.archive[&batch_id].manifest();
        let event_binding_digest = match precomputed_event_binding_digest {
            Some(digest) => digest,
            None => AcceptedBatchEvidence::binding_digest_for(
                batch_id,
                manifest_fingerprint,
                manifest.semantic_effect_digest(),
                manifest.dependency_frontier(),
                manifest.causal_dependency_heads(),
            )?,
        };
        let causal_clock = if let Some(store) = &self.scratch {
            super::causal_index::batch_record(store, &roots, batch_id)
                .map_err(|error| EngineError::Archive(error.to_string()))?
                .ok_or_else(|| {
                    EngineError::Archive(format!(
                        "accepted batch {batch_id} has no authenticated causal record"
                    ))
                })?
                .clock()
                .to_vec()
        } else {
            self.derive_ephemeral_causal_clock(manifest)?
        };
        let (clock_root_key, clock_root_digest) = authenticated_causal_clock_root(&causal_clock)?;
        let causal_record_digest = accepted_causal_record_digest(
            batch_id,
            manifest_fingerprint,
            event_binding_digest,
            manifest.causal_dot(),
            clock_root_key,
            clock_root_digest,
        );
        let (batch_map_root_key, batch_map_root_digest) = if let Some(store) = &self.scratch {
            roots.accepted_batch_map_root = store
                .accepted_batch_map_upsert(
                    &roots.accepted_batch_map_root,
                    batch_id.as_uuid().into_bytes(),
                    causal_record_digest,
                )
                .map_err(|error| EngineError::Archive(error.to_string()))?;
            if roots.accepted_batch_map_root.count() != acceptance_sequence {
                return Err(EngineError::Archive(
                    "authenticated batch map count differs from accepted sequence".into(),
                ));
            }
            (
                roots.accepted_batch_map_root.root_key(),
                roots.accepted_batch_map_root.root_digest(),
            )
        } else {
            let mut entries = self.ephemeral_accepted_batch_entries.clone();
            entries.insert(batch_id, causal_record_digest);
            authenticated_map_root(&entries.into_iter().collect::<Vec<_>>())?
        };
        let affected_documents = changed_documents.into_values().collect::<Vec<_>>();
        let retained_bytes = accepted_batch_retained_bytes(&self.archive[&batch_id])?;
        let post_frontier_root = next_accepted_frontier_root(
            &prior_frontier_root,
            event_binding_digest,
            acceptance_sequence,
            new_document_count,
            retained_bytes,
            &affected_documents,
            document_map_root_key,
            document_map_root_digest,
            batch_map_root_key,
            batch_map_root_digest,
            reference_catalog_delta.post_root().clone(),
            scratch_root,
        )?;
        let evidence = AcceptedBatchEvidence {
            schema_version: ACCEPTED_EVIDENCE_SCHEMA_VERSION,
            batch_id,
            manifest_fingerprint,
            event_binding_digest,
            acceptance_sequence,
            prior_frontier_root,
            post_frontier_root,
            affected_documents,
            reference_catalog_delta: reference_catalog_delta.clone(),
        };
        if let Some(store) = &self.scratch {
            roots.accepted_sequence_root = store
                .append_accepted_sequence(
                    &roots.accepted_sequence_root,
                    acceptance_sequence,
                    batch_id,
                    postcard::to_allocvec(&evidence)
                        .map_err(|error| EngineError::Archive(error.to_string()))?,
                )
                .map_err(|error| EngineError::Archive(error.to_string()))?;
        }
        Ok((post_documents, evidence, roots))
    }

    fn commit_acceptance_evidence(
        &mut self,
        post_documents: Option<BTreeMap<DocumentId, DocumentDependencies>>,
        evidence: AcceptedBatchEvidence,
        roots: ScratchRoots,
    ) {
        self.next_acceptance_sequence = evidence.acceptance_sequence;
        self.accepted_frontier_root = evidence.post_frontier_root.clone();
        if self.scratch.is_some() {
            debug_assert!(post_documents.is_none());
            debug_assert!(self.accepted_frontier.is_empty());
            debug_assert!(self.accepted_sequence.is_empty());
            self.scratch_roots = roots;
        } else {
            let manifest = self.archive[&evidence.batch_id].manifest();
            let clock = self
                .derive_ephemeral_causal_clock(manifest)
                .expect("accepted inline causal clock was validated");
            let (clock_root_key, clock_root_digest) =
                authenticated_causal_clock_root(&clock).expect("canonical accepted causal clock");
            let record_digest = accepted_causal_record_digest(
                evidence.batch_id,
                evidence.manifest_fingerprint,
                evidence.event_binding_digest,
                manifest.causal_dot(),
                clock_root_key,
                clock_root_digest,
            );
            self.ephemeral_causal_clocks
                .insert(evidence.batch_id, clock);
            self.ephemeral_accepted_batch_entries
                .insert(evidence.batch_id, record_digest);
            self.accepted_frontier = post_documents.expect("inline accepted frontier");
            self.accepted_sequence
                .insert(evidence.acceptance_sequence, evidence.batch_id);
        }
    }

    /// Preflight the authenticated scratch current-path trie before durable
    /// acceptance publication. Its inputs are the semantic effect already
    /// checked against the accepted catalog transition; it never reads
    /// receipts, projections, or graph files.
    fn prepare_current_path_catalog_transition(
        &self,
        effect: &SemanticEffect,
        accepted_frontier_root: AcceptedFrontierRoot,
    ) -> Result<CurrentPathCatalogTransition, EngineError> {
        if effect.pages().len() > MAX_TRANSACTION_OPERATIONS {
            return Err(EngineError::Archive(
                "current-path catalog delta exceeds the transaction bound".into(),
            ));
        }
        if self.current_path_catalog.accepted_frontier_root != self.accepted_frontier_root {
            return Err(EngineError::Archive(
                "current-path catalog is not bound to the transition's prior accepted frontier"
                    .into(),
            ));
        }
        let Some(store) = self.scratch.as_ref() else {
            return Ok(CurrentPathCatalogTransition {
                catalog: CurrentPathCatalog {
                    root: ScratchAuthenticatedCatalogRoot::default(),
                    available: self.current_path_catalog.available && effect.pages().is_empty(),
                    accepted_frontier_root,
                },
            });
        };
        if !self.current_path_catalog.available {
            return Err(EngineError::Archive(
                "authenticated current-path catalog authority is unavailable".into(),
            ));
        }
        let mut desired = BTreeMap::<PageId, Option<CurrentPathCatalogStoredRow>>::new();
        for delta in effect.pages() {
            let before = delta
                .before
                .as_ref()
                .and_then(current_path_catalog_row_from_page_state);
            let after = delta
                .after
                .as_ref()
                .and_then(current_path_catalog_row_from_page_state);
            if let Some(after) = &after {
                if after.path.as_str().len() > MAX_CURRENT_PATH_CURSOR_PATH_BYTES {
                    return Err(EngineError::Archive(format!(
                        "current-path catalog path for {} exceeds {} bytes",
                        delta.page_id, MAX_CURRENT_PATH_CURSOR_PATH_BYTES
                    )));
                }
            }
            if desired.insert(delta.page_id, after).is_some() {
                return Err(EngineError::Archive(
                    "current-path catalog delta contains a duplicate page".into(),
                ));
            }
            let stored = store
                .authenticated_catalog_lookup(
                    &self.current_path_catalog.root,
                    delta.page_id.as_uuid().into_bytes(),
                )
                .map_err(|error| EngineError::Archive(error.to_string()))?
                .map(|encoded| decode_current_path_catalog_row(&encoded))
                .transpose()?;
            if stored.as_ref() != before.as_ref() {
                return Err(EngineError::Archive(
                    "current-path catalog is missing or corrupt before-row authority".into(),
                ));
            }
        }

        let mut root = self.current_path_catalog.root.clone();
        for (page_id, after) in desired {
            let key = page_id.as_uuid().into_bytes();
            root = store
                .authenticated_catalog_remove(&root, key)
                .map_err(|error| EngineError::Archive(error.to_string()))?;
            if let Some(after) = after {
                let encoded = encode_current_path_catalog_row(&after)?;
                root = store
                    .authenticated_catalog_upsert(&root, key, &encoded)
                    .map_err(|error| EngineError::Archive(error.to_string()))?;
            }
        }
        if root.count() > MAX_DOCUMENT_ENTRIES as u64 {
            return Err(EngineError::Archive(
                "current-path catalog entry bound exceeded".into(),
            ));
        }
        Ok(CurrentPathCatalogTransition {
            catalog: CurrentPathCatalog {
                root,
                available: true,
                accepted_frontier_root,
            },
        })
    }

    fn commit_current_path_catalog_transition(&mut self, transition: CurrentPathCatalogTransition) {
        self.current_path_catalog = transition.catalog;
        // An accepted frontier transition makes every outstanding continuation
        // stale. Dropping them also prevents abandoned cursors from consuming
        // the bounded cursor table.
        self.current_path_cursor_book.borrow_mut().active.clear();
    }

    fn derive_ephemeral_causal_clock(
        &self,
        manifest: &OperationBatch,
    ) -> Result<Vec<(CausalPeerId, u64)>, EngineError> {
        self.derive_inline_causal_clock(
            &self.scratch_roots,
            manifest.causal_dot(),
            manifest.causal_dependency_heads(),
        )
    }

    /// Derive one candidate sparse causal clock from its declared direct heads.
    ///
    /// This is used before a candidate has an authenticated causal record of
    /// its own.  It intentionally reads only the direct parent records (or
    /// inline parent clocks), so callers never need to walk causal ancestry to
    /// answer causal-containment questions for a pending transition.
    fn derive_inline_causal_clock(
        &self,
        scratch_roots: &ScratchRoots,
        causal_dot: BatchCausalDot,
        direct_causal_heads: &[BatchId],
    ) -> Result<Vec<(CausalPeerId, u64)>, EngineError> {
        let mut clock = BTreeMap::<CausalPeerId, u64>::new();
        if let Some(store) = &self.scratch {
            for parent in direct_causal_heads {
                let parent_clock = super::causal_index::batch_record(store, scratch_roots, *parent)
                    .map_err(|error| EngineError::Archive(error.to_string()))?
                    .ok_or(EngineError::MissingDependency(*parent))?;
                for (peer, counter) in parent_clock.clock() {
                    clock
                        .entry(*peer)
                        .and_modify(|current| *current = (*current).max(*counter))
                        .or_insert(*counter);
                }
            }
        } else {
            for parent in direct_causal_heads {
                let parent_clock = self
                    .ephemeral_causal_clocks
                    .get(parent)
                    .ok_or(EngineError::MissingDependency(*parent))?;
                for (peer, counter) in parent_clock {
                    clock
                        .entry(*peer)
                        .and_modify(|current| *current = (*current).max(*counter))
                        .or_insert(*counter);
                }
            }
        }
        let expected = clock
            .get(&causal_dot.peer_id())
            .copied()
            .unwrap_or(0)
            .checked_add(1)
            .ok_or_else(|| EngineError::Archive("causal counter overflowed".into()))?;
        if causal_dot.counter() != expected {
            return Err(EngineError::InvalidCrdt(format!(
                "causal dot {:?}:{} is not gap-free; expected {expected}",
                causal_dot.peer_id(),
                causal_dot.counter()
            )));
        }
        clock.insert(causal_dot.peer_id(), causal_dot.counter());
        Ok(clock.into_iter().collect())
    }

    fn accepted_document_dependencies(
        &self,
        document_id: DocumentId,
    ) -> Result<Option<DocumentDependencies>, EngineError> {
        if let Some(store) = &self.scratch {
            let bytes = store
                .lookup(
                    &self.scratch_roots.accepted_frontier_root,
                    super::scratch_store::ScratchPageKind::AcceptedFrontier,
                    document_id.as_uuid().as_bytes(),
                )
                .map_err(|error| EngineError::Archive(error.to_string()))?;
            return bytes
                .map(|bytes| decode_accepted_document(document_id, &bytes))
                .transpose();
        }
        Ok(self.accepted_frontier.get(&document_id).cloned())
    }

